CREATE TABLE customers (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL UNIQUE,phone VARCHAR(50) NULL,CONSTRAINT fk_customer_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE sites (id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NOT NULL,name VARCHAR(255) NOT NULL,address VARCHAR(500) NOT NULL,city VARCHAR(100),state VARCHAR(100),postal_code VARCHAR(30),CONSTRAINT fk_site_customer FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE work_orders (id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NOT NULL,site_id BIGINT NOT NULL,technician_id BIGINT NULL,title VARCHAR(255) NOT NULL,description VARCHAR(2000),status VARCHAR(30) NOT NULL,scheduled_at DATETIME NULL,created_at DATETIME NOT NULL,CONSTRAINT fk_wo_customer FOREIGN KEY(customer_id) REFERENCES customers(id),CONSTRAINT fk_wo_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_wo_tech FOREIGN KEY(technician_id) REFERENCES users(id));
CREATE TABLE work_order_status_history (id BIGINT PRIMARY KEY AUTO_INCREMENT,work_order_id BIGINT NOT NULL,status VARCHAR(30) NOT NULL,changed_by BIGINT NULL,changed_at DATETIME NOT NULL,CONSTRAINT fk_hist_wo FOREIGN KEY(work_order_id) REFERENCES work_orders(id),CONSTRAINT fk_hist_user FOREIGN KEY(changed_by) REFERENCES users(id));
CREATE TABLE parts (id BIGINT PRIMARY KEY AUTO_INCREMENT,part_number VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,quantity INT NOT NULL DEFAULT 0);
CREATE TABLE part_usage (id BIGINT PRIMARY KEY AUTO_INCREMENT,work_order_id BIGINT NOT NULL,part_id BIGINT NOT NULL,quantity INT NOT NULL,CONSTRAINT fk_usage_wo FOREIGN KEY(work_order_id) REFERENCES work_orders(id),CONSTRAINT fk_usage_part FOREIGN KEY(part_id) REFERENCES parts(id));
CREATE TABLE time_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT,work_order_id BIGINT NOT NULL,technician_id BIGINT NOT NULL,start_time DATETIME,end_time DATETIME,CONSTRAINT fk_time_wo FOREIGN KEY(work_order_id) REFERENCES work_orders(id),CONSTRAINT fk_time_tech FOREIGN KEY(technician_id) REFERENCES users(id));
CREATE TABLE notifications (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,message VARCHAR(1000) NOT NULL,read_flag BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME NOT NULL,CONSTRAINT fk_notification_user FOREIGN KEY(user_id) REFERENCES users(id));
